      }
    }
    .BadgeSidebar__RootDiv-sc-oi03p1-0 {
      background: @surface0;
      .SvgIconWrapper__SvgIconDiv-sc-1u203y2-0 {
        svg path {
          fill: @text;
        }
        &:hover {
          background: @surface1;
        }
      }
      .BadgeSidebar__ChallengeLevelsDiv-sc-oi03p1-10 {
        border-color: @overlay0;
      }
    }
